\section{Introduction}

\subsection{Free witnesses and the square-root barrier}

Let $N=pq$ be a semiprime. A \emph{free witness} is a function $S$ such that $S(N)$ is computable from $N$ alone, without knowledge of $p$ and $q$, and such that $S(N)$ constrains the pair $(p,q)$ enough to help recover it. A cheap free witness would be a mathematical event of the first order.

A natural family of candidates comes from point counts on curves modulo $N$ weighted by the Jacobi symbol. The Jacobi symbol $\jac{a}{N}$ is the unique completely multiplicative extension of the Legendre symbol in its lower argument, and it is computable in $O(\log^{2}N)$ bit operations by a Euclidean algorithm driven by quadratic reciprocity---crucially, \emph{without} factoring $N$. Character sums built from it are therefore genuinely free.

The candidate studied here is the Jacobi-signed circle count $W(N)$ above. It is attractive for three reasons: it is multiplicative, so it ``knows'' that $N$ splits; it fluctuates on the hard family of semiprimes with both factors $\equiv 1 \pmod 4$; and at each such prime it computes a genuine arithmetic invariant, the odd leg of the two-square decomposition. It is also, as we show in four independent ways, useless as a witness---and the reasons are more interesting than the conclusion.

\subsection{Notation and background}

Throughout, $p$ denotes an odd prime and $N$ an odd positive integer; $\chi=\jac{\cdot}{p}$ is the quadratic (Legendre) character of $\F_{p}$, extended by $\chi(0)=0$; $\omega(N)$ is the number of distinct prime factors of $N$; $v_{2}$ is the $2$-adic valuation. A \emph{multiplicative character} $\psi$ of $\F_{p}$ is a homomorphism $\F_{p}^{\times}\to\C^{\times}$ extended by $\psi(0)=0$. The \emph{Jacobi sum} of two characters is
\[
  J(\alpha,\beta) \;=\; \sum_{x\in\F_{p}} \alpha(x)\,\beta(1-x).
\]

We use freely the following classical facts.

\begin{itemize}
  \item[(F1)] \emph{Orthogonality.} If $\psi\ne 1$ then $\sum_{x\in\F_{p}}\psi(x)=0$.
  \item[(F2)] \emph{Square-root counting.} For $a\in\F_{p}$ and $p$ odd, $\#\{y: y^{2}=a\}=1+\chi(a)$.
  \item[(F3)] \emph{The character group.} $\F_{p}^{\times}$ is cyclic of order $p-1$ and so is its character group. If $\psi_{j}$ sends a fixed generator $g$ to $e^{2\pi i j/(p-1)}$, then $\psi_{j}(-1)=(-1)^{j}$; hence $\psi$ is \emph{even} ($\psi(-1)=1$) if and only if $\psi$ is a square in the character group, and $\chi=\psi_{(p-1)/2}$ is the unique character of order $2$.
  \item[(F4)] \emph{Jacobi sum modulus.} If $\alpha,\beta,\alpha\beta$ are all nontrivial then $J(\alpha,\beta)\overline{J(\alpha,\beta)}=p$.
  \item[(F5)] \emph{Fermat/Gauss.} Every prime $p\equiv 1 \pmod 4$ is $p=a^{2}+b^{2}$ with $a$ odd, uniquely up to signs, and $W(p)=2a$ for a suitable sign of $a$; for $p\equiv 3\pmod 4$, $W(p)=0$.
  \item[(F6)] \emph{Multiplicativity.} $W(mn)=W(m)W(n)$ for coprime odd $m,n$ (Theorem~\ref{thm:univmul} below).
\end{itemize}

\subsection{Reduction of the double sum}

Fix $x$; by (F2) the number of $y$ with $x^{2}+y^{2}=1$ equals $1+\chi(1-x^{2})$. Hence for any weight $w:\F_{p}\to\C$,
\begin{equation}\label{eq:reduce}
  \sum_{x^{2}+y^{2}=1} w(x) \;=\; \sum_{x} w(x)\bigl(1+\chi(1-x^{2})\bigr).
\end{equation}
Taking $w=\chi$, using $\chi(x)\chi(1-x^{2})=\chi(x-x^{3})$ and (F1),
\begin{equation}\label{eq:cubic}
  W(p) \;=\; \sum_{x\in\F_{p}} \chi(x-x^{3}),
\end{equation}
which is, up to sign, the trace of Frobenius of the elliptic curve $y^{2}=x^{3}-x$: the circle with quadratic weight is an elliptic curve in disguise, and the Weil floor is the Hasse bound.

\section{Character weights: the floor is a property of the circle}

\begin{definition}
For a multiplicative character $\psi$ of $\F_{p}$, the \emph{$\psi$-weighted circle count} is
\[
  W_{\psi}(p) \;=\; \sum_{\substack{x,y\in\F_{p}\\ x^{2}+y^{2}=1}} \psi(x).
\]
\end{definition}

For $\psi=\chi$ this is $W(p)$; for $\psi=1$ it equals $p-3$ when $p\equiv 1\pmod 4$ and $p+1$ when $p\equiv 3\pmod 4$.

\begin{theorem}[Odd weights are blind]\label{thm:odd}
If $\psi(-1)=-1$ then $W_{\psi}(p)=0$.
\end{theorem}

\begin{proof}
The involution $(x,y)\mapsto(-x,y)$ permutes the solutions of $x^{2}+y^{2}=1$, and $\psi(-x)=\psi(-1)\psi(x)=-\psi(x)$. Reindexing gives $W_{\psi}(p)=-W_{\psi}(p)$, hence $2W_{\psi}(p)=0$, hence $W_{\psi}(p)=0$ in characteristic zero.
\end{proof}

By (F3) exactly half of all characters are odd. Theorem~\ref{thm:odd} contains as a special case the classical vanishing $W(p)=0$ for $p\equiv 3\pmod 4$, since then $\chi(-1)=-1$.

\begin{lemma}[One-variable reduction]\label{lem:onevar}
For every character $\psi$,
\[
  W_{\psi}(p)=\sum_{x\in\F_{p}} \psi(x)\bigl(\chi(1-x^{2})+1\bigr).
\]
\end{lemma}

\begin{proof}
This is \eqref{eq:reduce}, i.e.\ (F2) applied to $a=1-x^{2}$ for each fixed $x$.
\end{proof}

\begin{lemma}[Pushforward along squaring]\label{lem:push}
For every $F:\F_{p}\to\C$, \quad $\displaystyle \sum_{c\in\F_{p}}F(c^{2})=\sum_{d\in\F_{p}}\bigl(\chi(d)+1\bigr)F(d)$.
\end{lemma}

\begin{proof}
Group the left-hand sum by $d=c^{2}$; by (F2) the fibre over $d$ has $1+\chi(d)$ elements.
\end{proof}

\begin{theorem}[Jacobi-sum decomposition]\label{thm:decomp}
Let $\xi$ be a character of $\F_{p}$ with $\xi^{2}\ne 1$. Then
\[
  W_{\xi^{2}}(p) \;=\; J(\xi,\chi)\;+\;J(\chi\xi,\chi).
\]
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:onevar} with $\psi=\xi^{2}$, and $\xi^{2}(x)=\xi(x^{2})$,
\[
  W_{\xi^{2}}(p)=\sum_{x}\xi^{2}(x)+\sum_{x}\xi(x^{2})\chi(1-x^{2}).
\]
The first sum vanishes by (F1) since $\xi^{2}\ne 1$. Apply Lemma~\ref{lem:push} to the second with $F(d)=\xi(d)\chi(1-d)$:
\[
  \sum_{x}\xi(x^{2})\chi(1-x^{2})=\sum_{d}\bigl(\chi(d)+1\bigr)\xi(d)\chi(1-d)
   = \sum_{d}(\chi\xi)(d)\chi(1-d)+\sum_{d}\xi(d)\chi(1-d),
\]
which is $J(\chi\xi,\chi)+J(\xi,\chi)$.
\end{proof}

\begin{theorem}[Modulus of a Jacobi sum]\label{thm:jacnorm}
If $\alpha,\beta$ and $\alpha\beta$ are all nontrivial then $|J(\alpha,\beta)|=\sqrt{p}$.
\end{theorem}

\begin{proof}
Complex conjugation inverts character values, so $\overline{J(\alpha,\beta)}=J(\alpha^{-1},\beta^{-1})$. The classical identity $J(\alpha,\beta)J(\alpha^{-1},\beta^{-1})=p$, valid whenever $\alpha,\beta,\alpha\beta\ne 1$, then gives $|J(\alpha,\beta)|^{2}=p$.
\end{proof}

\begin{lemma}[Classification of quadratic characters]\label{lem:class}
If $\xi^{2}=1$ then $\xi=1$ or $\xi=\chi$.
\end{lemma}

\begin{proof}
Let $g$ generate $\F_{p}^{\times}$. Then $\xi(g)^{2}=1$, so $\xi(g)=\pm 1$, and a character is determined by its value at a generator. If $\xi(g)=1$ then $\xi=1$. If $\xi(g)=-1$, note that a generator is a quadratic non-residue (otherwise $g^{(p-1)/2}=1$ and the order of $g$ would be at most $(p-1)/2$), so $\chi(g)=-1=\xi(g)$ and $\xi=\chi$.
\end{proof}

Equivalently, $\xi^{2}\ne1$ if and only if $\xi\ne1$ and $\chi\xi\ne1$.

\begin{theorem}[Character-agnostic Weil floor]\label{thm:main1}
Let $p$ be an odd prime and $\xi$ a character with $\xi\ne 1$ and $\chi\xi\ne 1$. Then
\[
  \bigl|W_{\xi^{2}}(p)\bigr| \;\le\; 2\sqrt{p}.
\]
The constant $2$ is absolute; in particular it does not depend on the order of $\xi$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:class}, $\xi^{2}\ne1$, so Theorem~\ref{thm:decomp} gives $W_{\xi^{2}}(p)=J(\xi,\chi)+J(\chi\xi,\chi)$. For the first sum, $\xi\ne1$, $\chi\ne1$ and $\xi\chi\ne1$, so $|J(\xi,\chi)|=\sqrt p$ by Theorem~\ref{thm:jacnorm}. For the second, $\chi\xi\ne1$, $\chi\ne1$ and $(\chi\xi)\chi=\xi\chi^{2}=\xi\ne1$, so $|J(\chi\xi,\chi)|=\sqrt p$. Apply the triangle inequality.
\end{proof}

\begin{corollary}\label{cor:allweights}
For every nontrivial multiplicative character $\psi$ of $\F_{p}$ one has $|W_{\psi}(p)|\le 2\sqrt p$; and if $\psi$ is odd then $W_{\psi}(p)=0$ exactly.
\end{corollary}

\begin{proof}
If $\psi$ is odd, apply Theorem~\ref{thm:odd}. If $\psi$ is even and $\psi\ne\chi$, write $\psi=\xi^{2}$ by (F3); then $\xi^{2}\ne1$, so $\xi\notin\{1,\chi\}$ by Lemma~\ref{lem:class} and Theorem~\ref{thm:main1} applies. The remaining case $\psi=\chi$ with $p\equiv1\pmod4$ is the classical floor $|W(p)|=|2a|\le2\sqrt p$ from (F5).
\end{proof}

\begin{remark}[Non-vacuity]
Whenever $p\equiv1\pmod4$ we have $4\mid p-1$, so $\F_{p}^{\times}$ carries a character $\xi$ of order exactly $4$, which is neither trivial nor quadratic. For such $\xi$ one has $\xi^{2}=\chi$, and Theorem~\ref{thm:decomp} recovers the classical expression of $W(p)=2a$ as a sum of two conjugate Jacobi sums. If $8\mid p-1$, taking $\xi$ of order $8$ or more produces genuinely new even weights $\xi^{2}\ne\chi$, still bounded by $2\sqrt p$.
\end{remark}

\begin{remark}[What was conjectured, and what is true]
One might expect a weight of order $d$ to obey $|W_{\psi}(p)|\le d\sqrt p$, the factor $d$ measuring the complexity of the weight. Theorem~\ref{thm:main1} shows the truth is stronger and simpler: the circle always produces exactly two Jacobi sums, whatever the weight. The floor is a property of the circle, not of the weight.
\end{remark}

\section{The exact Weil deficiency, and a sharp floor}

Write $p\equiv1\pmod4$ as $p=a^{2}+b^{2}$ with $W(p)=2a$ and $a$ odd (F5).

\begin{lemma}[Parity of the companion leg]\label{lem:parity}
If $p\equiv1\pmod4$, $p=a^{2}+b^{2}$ and $a$ is odd, then $b$ is even.
\end{lemma}

\begin{proof}
If $a=2k+1$ and $b=2m+1$ then $a^{2}+b^{2}=4(k^{2}+k+m^{2}+m)+2\equiv2\pmod4$, contradicting $p\equiv1\pmod4$.
\end{proof}

\begin{theorem}[Exact deficiency]\label{thm:def}
For $p\equiv1\pmod4$, with notation as above,
\[
  4p-W(p)^{2} \;=\; 4b^{2}.
\]
\end{theorem}

\begin{proof}
$4p-W(p)^{2}=4(a^{2}+b^{2})-(2a)^{2}=4b^{2}$.
\end{proof}

Trivial as an identity, this is the structural content of the Weil bound here: the bound is not an estimate but an exact equation with a nonnegative correction term of known arithmetic meaning.

\begin{lemma}\label{lem:bnonzero}
A prime is never a perfect square; hence $b\ne0$ in any representation $p=a^{2}+b^{2}$.
\end{lemma}

\begin{proof}
If $b=0$ then $p=a^{2}$, so $|a|\mid p$; $|a|=1$ gives $p=1$ and $|a|=p$ gives $p=p^{2}$, both impossible.
\end{proof}

\begin{theorem}[Sharp floor]\label{thm:sharp}
For every prime $p\equiv1\pmod4$,
\[
  W(p)^{2}\;\le\;4p-16,
\]
and the constant $16$ is optimal: equality holds exactly when $|b|=2$, i.e.\ at the primes $p=a^{2}+4$, for instance $p=5,13,29,53,173,229,293$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:parity}, $b$ is even; by Lemma~\ref{lem:bnonzero}, $b\ne0$; so $b^{2}\ge4$ and $4b^{2}\ge16$. Apply Theorem~\ref{thm:def}.
\end{proof}

\begin{theorem}[Near-attainment is Diophantine]\label{thm:near}
Let $u,v$ be positive integers and $\varepsilon=u/v$. Then
\[
  W(p)^{2}>(1-\varepsilon)\cdot 4p \iff v\,b^{2}<u\,p.
\]
\end{theorem}

\begin{proof}
Multiply the left inequality by $v$ and substitute $W(p)^{2}=4p-4b^{2}$ from Theorem~\ref{thm:def}: it becomes $v(4p-4b^{2})>(v-u)4p$, i.e.\ $4up>4vb^{2}$.
\end{proof}

Thus ``how often is the Weil floor nearly attained?'' is exactly ``how often is a prime of the form $a^{2}+b^{2}$ with $b=O(p^{\varepsilon/2})$?''---a question about primes represented by thin quadratic families, of Landau--Ramanujan type. The often-quoted example $p=173$, with $W(p)^{2}/4p=676/692=97.69\%$, is completely explained: $173=13^{2}+2^{2}$, the even leg is minimal, and $4\cdot173-26^{2}=16$ exactly.

