\section{Two-adic content}

\begin{lemma}\label{lem:2adicprime}
For $p\equiv1\pmod4$, $W(p)=2s$ with $s$ odd; for $p\equiv3\pmod4$, $W(p)=0$.
\end{lemma}

\begin{proof}
This is (F5) together with Lemma~\ref{lem:parity}.
\end{proof}

\begin{theorem}[Semiprime valuation]\label{thm:semi2adic}
Let $p\ne q$ be primes with $p\equiv q\equiv1\pmod4$. Then $W(pq)=4s$ with $s$ odd; equivalently $4\mid W(pq)$ and $8\nmid W(pq)$, i.e.\ $v_{2}(W(pq))=2$ exactly. In particular $W(pq)\ne0$.
\end{theorem}

\begin{proof}
Write $W(p)=2a$, $W(q)=2c$ with $a,c$ odd (Lemma~\ref{lem:2adicprime}). Multiplicativity gives $W(pq)=4ac$, and $ac$ is odd since $2$ is prime.
\end{proof}

\begin{theorem}[Squarefree case]\label{thm:sqfree2adic}
Let $N$ be squarefree with every prime factor $\equiv1\pmod4$. Then $W(N)=2^{\omega(N)}s$ with $s$ odd; equivalently $v_{2}(W(N))=\omega(N)$.
\end{theorem}

\begin{proof}
Induct over the set of prime factors, using $N=\prod_{p\mid N}p$, the coprimality of each prime with the product of the others, multiplicativity, Lemma~\ref{lem:2adicprime} at each prime, and the fact that a product of odd integers is odd. The base case $N=1$ gives $W(1)=1$.
\end{proof}

\begin{theorem}[Exact vanishing criterion]\label{thm:vanish}
For distinct odd primes $p,q$: \; $W(pq)=0$ if and only if $p\equiv3\pmod4$ or $q\equiv3\pmod4$.
\end{theorem}

\begin{proof}
($\Leftarrow$) Lemma~\ref{lem:2adicprime} and multiplicativity. ($\Rightarrow$) If both are $\equiv1\pmod4$ then $W(pq)\ne0$ by Theorem~\ref{thm:semi2adic}.
\end{proof}

\begin{theorem}[Blindness to the split]\label{thm:blind}
On the family of semiprimes $N=pq$ with $p\ne q$ and $p\equiv q\equiv1\pmod4$, the quantity $v_{2}(W(N))$ is the constant $2$. Hence for any two such $N,N'$ we have $v_{2}(W(N))=v_{2}(W(N'))$.
\end{theorem}

This is the correct formulation of ``the $2$-adic content carries no information''. The tempting alternative---that the content is publicly computable from $N \bmod 4$---is false.

\begin{theorem}[Refutation]\label{thm:refute}
There exist semiprimes $M,N$ with $M\equiv N\pmod4$ but $W(M)=0\ne W(N)$: take $M=21=3\cdot7$ and $N=85=5\cdot17$, so that $21\equiv85\equiv1\pmod4$ while
\[
  W(21)=0,\qquad W(85)=-4.
\]
Consequently there is no function $f$ with $W(N)=f(N \bmod 4)$ for all odd $N$; the signed circle count is not a residue dial.
\end{theorem}

\subsection{The Brahmagupta refinement}

\begin{theorem}[Four-square refinement]\label{thm:4sq}
Let $p\ne q$ be primes $\equiv1\pmod4$ with $p=a^{2}+b^{2}$, $q=c^{2}+d^{2}$, $a,c$ odd, $W(p)=2a$, $W(q)=2c$. Put $s=ac$, $u=ad$, $v=bc$, $w=bd$. Then
\[
  pq=s^{2}+u^{2}+v^{2}+w^{2},\qquad W(pq)=4s \text{ with } s \text{ odd},
\]
\[
  16\,pq \;=\; W(pq)^{2}+(4u)^{2}+(4v)^{2}+(4w)^{2}.
\]
\end{theorem}

\begin{proof}
Expand $(a^{2}+b^{2})(c^{2}+d^{2})=(ac)^{2}+(ad)^{2}+(bc)^{2}+(bd)^{2}$ and multiply by $16$, using $W(pq)=4ac$.
\end{proof}

The last display is an exact refinement of the semiprime floor $W(N)^{2}\le16N$: the deficiency $16N-W(N)^{2}$ is an explicit sum of three squares.

\begin{theorem}[The statistic reads a Gaussian coordinate of $N$]\label{thm:gauss}
In the situation of Theorem~\ref{thm:4sq} there is a two-square representation $N=pq=u^{2}+v^{2}$ with $u$ odd such that
\[
  W(N)\equiv 4u \pmod{16}.
\]
\end{theorem}

\begin{proof}
Take $u=ac-bd$, $v=ad+bc$ (Brahmagupta's identity). Then $u$ is odd, since $ac$ is odd and $bd$ is even by Lemma~\ref{lem:parity}. Writing $b=2b'$, $d=2d'$, we get $W(N)-4u=4ac-4(ac-bd)=4bd=16b'd'$.
\end{proof}

The Gaussian coordinates $(u,v)$ of $N$ are an invariant of $N$ itself. So $W(N)\bmod16$ reports a conserved quantity of the modulus, not a feature of the split: any large signal in one leg is compensated by the other, with $N=u^{2}+v^{2}$ conserved.

\section{Universality: multiplicativity is free, conics are constants}

\begin{definition}
For $f\in\Z[X]$ and odd $N$, set $\displaystyle S_{f}(N)=\sum_{x\in\Z/N}\jac{f(x)}{N}$, where $f(x)$ is evaluated in $\Z/N$.
\end{definition}

For $f=X-X^{3}$ this is $W$, by \eqref{eq:cubic}.

\begin{theorem}[Universal multiplicativity]\label{thm:univmul}
For every $f\in\Z[X]$ and coprime odd $m,n$: \; $S_{f}(mn)=S_{f}(m)\,S_{f}(n)$.
\end{theorem}

\begin{proof}
The Chinese Remainder Theorem gives a ring isomorphism $\Z/mn\cong\Z/m\times\Z/n$. Polynomial evaluation commutes with ring homomorphisms, so the reduction of $f(x)$ modulo $m$ is $f(x \bmod m)$, and similarly for $n$. The Jacobi symbol splits, $\jac{a}{mn}=\jac{a}{m}\jac{a}{n}$, each factor depending only on $a$ modulo the respective modulus. Hence the summand factors as a product of a function of $x\bmod m$ and a function of $x\bmod n$, and the sum over $\Z/mn$ becomes a product of sums.
\end{proof}

The moral is decisive: multiplicativity is a theorem about the Chinese Remainder Theorem, not about the curve. That $W(N)$ splits along the factorisation is therefore no evidence at all of leakage---every polynomial weight does it, including the provably constant ones.

\begin{theorem}[Conic evaluation]\label{thm:conic}
Let $p$ be an odd prime, $r,s\in\Z$, and $f(X)=(X-r)(X-s)$. Then
\[
  S_{f}(p)=\begin{cases} p-1, & r\equiv s \pmod p,\\ -1, & r\not\equiv s \pmod p.\end{cases}
\]
\end{theorem}

\begin{proof}
Modulo $p$ the Jacobi symbol is $\chi$. If $r\equiv s$, the sum is $\sum_{x}\chi((x-r)^{2})=\#\{x\ne r\}=p-1$. Otherwise put $x=r+t$ and $c=r-s$: the sum becomes $\sum_{t}\chi(t)\chi(t+c)$. For $t\ne0$, $\chi(t)\chi(t+c)=\chi(t^{2})\chi(1+ct^{-1})=\chi(1+ct^{-1})$, and as $t$ ranges over the nonzero residues, $1+ct^{-1}$ ranges over all residues except $1$; so the sum is $\sum_{z\ne1}\chi(z)=-\chi(1)=-1$ by (F1).
\end{proof}

\begin{corollary}[Squarefree law]\label{cor:sqfreeconic}
If $N$ is squarefree with all prime factors odd and none dividing $r-s$, then $S_{f}(N)=(-1)^{\omega(N)}$. In particular $S_{f}(pq)=+1$ for every such semiprime.
\end{corollary}

So a separable conic statistic returns the constant $+1$ at every semiprime in its range of validity: it carries no information at all, and does not even reach the square-root floor---its fluctuation is zero.

\begin{theorem}[Strict separation]\label{thm:sep}
There is a semiprime at which the circle statistic differs from every separable conic statistic: at $N=85=5\cdot17$ every separable conic weight gives $+1$, whereas $W(85)=-4$.
\end{theorem}

The dichotomy this exhibits is the heart of the matter. In degree $\le2$ the statistic is a constant, because the curve $y^{2}=f(x)$ is rational and its point count has no error term. In degree $3$ the statistic fluctuates, of size exactly $\sqrt p$, because $y^{2}=f(x)$ is an elliptic curve and the Hasse--Weil bound both permits and caps the fluctuation. The interesting regime and the impossible regime coincide.

\section{Algorithms and complexity}

\textbf{A. Jacobi symbol.} Given odd $N>0$ and $a$, compute $\jac{a}{N}$ by a Euclidean loop: reduce $a$ modulo $N$, extract powers of $2$ (flipping the sign when $N\equiv3,5\pmod8$), then swap arguments with a sign flip when both are $\equiv3\pmod4$. Cost $O(\log^{2}N)$ bit operations; no factorisation required.

\textbf{B. Direct signed circle count.} $W(N)=\sum_{x=0}^{N-1}\jac{x-x^{3}}{N}$, costing $N$ Jacobi symbols, i.e.\ $N^{1+o(1)}$: polynomial in $N$, exponential in $\log N$.

\textbf{C. Factored evaluation.} With $N=\prod_{i}p_{i}$ squarefree known, $W(N)=\prod_{i}W(p_{i})$, where $W(p)=0$ for $p\equiv3\pmod4$ and $W(p)=\pm2a$ with $p=a^{2}+b^{2}$, $a$ odd, computable in $\mathrm{polylog}(p)$ time by Cornacchia's algorithm. Cost $\mathrm{polylog}(N)$.

The gap between B and C is exactly the free-witness gap. The theorems above show that paying the expensive cost buys no information about the split: the value is pinned by the Weil floor and its coarse arithmetic is determined by invariants of $N$ itself.

\textbf{D. Character-weighted counts.} Fix a primitive root $g$ modulo $p$, tabulate discrete logarithms in $O(p)$ time, and evaluate $\psi_{j}(x)=e^{2\pi i j\log_{g}x/(p-1)}$. The circle count is a sum over the $p\pm1$ points, and each Jacobi sum a single sum of length $p$; the two sides of Theorem~\ref{thm:decomp} then agree to machine precision.

\section{Discussion}

\subsection{Why the four results are one result}

Each section removes one degree of freedom from the search for a leaking statistic.
Theorem~\ref{thm:univmul} removes the modulus degree of freedom: multiplicativity holds for every weight, so nothing is learned from the fact that the statistic factors. Corollary~\ref{cor:sqfreeconic} removes the low-degree direction: conics are constants, so only degree $\ge3$ fluctuates at all. Theorem~\ref{thm:main1} removes the weight degree of freedom: every character weight produces at most two Jacobi sums, each of modulus exactly $\sqrt p$. Theorem~\ref{thm:def} removes the near-attainment hope: the deficiency is an exact square, so approaching the ceiling means $p$ sits just above a square, and the bound only improves to $4p-16$. Theorems~\ref{thm:blind} and~\ref{thm:gauss} remove the arithmetic-fine-structure hope: the $2$-adic content is $\omega(N)$, constant on the hard family, and $W(N)\bmod16$ reports the odd Gaussian coordinate of $N$.

Together: the statistic is a number of size $\le4\sqrt N$ whose coarse arithmetic is determined by invariants of $N$ and whose fine arithmetic is capped by Hasse--Weil. A semiprime's factorisation needs about $\tfrac12\log_{2}N$ bits; the value has room for about that many bits, but the constraints show they are the wrong bits---functions of $N$, not of the split.

\subsection{Relation to classical theory}

Identity \eqref{eq:cubic} exhibits $W(p)$ as the trace of Frobenius of $y^{2}=x^{3}-x$, the congruent-number curve with complex multiplication by $\Z[i]$; the formula $W(p)=2a$ is Gauss's evaluation of the corresponding Jacobsthal sum. Theorem~\ref{thm:decomp} is the circle-sum incarnation of the classical fact that CM point counts are Jacobi sums, and Theorem~\ref{thm:jacnorm} is the Riemann hypothesis for curves in the one case Gauss could prove by hand. What is new here is uniformity: the constant $2$ in Theorem~\ref{thm:main1} is independent of the order of the weight, and Theorem~\ref{thm:def} converts the analytic near-attainment question into a Diophantine one.

\subsection{An information-theoretic reading}

Say a statistic \emph{leaks} on a family of semiprimes if the conditional distribution of the split given its value differs materially from the unconditional one. Our results give three levels of non-leakage: exact zero information (separable conic statistics are constant, Corollary~\ref{cor:sqfreeconic}); constant coarse invariants ($v_{2}(W(N))=2$ identically on the hard family, Theorem~\ref{thm:blind}, and $W(N)\bmod16$ a function of $N$'s Gaussian coordinates, Theorem~\ref{thm:gauss}); and capped fine information ($|W(N)|\le4\sqrt N$ with the per-prime constraint $|W(p)|\le\sqrt{4p-16}$ and the exact conservation law of Theorem~\ref{thm:4sq}). Only the third is quantitative, and it is where the Weil floor does its work.

\section{Future directions}

\textbf{D1. The cubic is the unique weight family with a nonconstant square-root signal.} For $f$ of degree $d\ge1$ not a constant times a square, one expects $|S_{f}(p)|\le(d-1)\sqrt p$, with equality possible only for $d\ge3$; for $d\le2$ the statistic is constant in $p$, so the entire conic-witness family is degenerate and $\sqrt p$-fluctuation begins exactly at the elliptic degree.

\textbf{D2. Two-adic valuations of character-weighted counts.} For a general character weight and composite modulus, the $\pi$-adic content of $W_{\psi}(N)$ (for $\pi$ above $2$ in the relevant cyclotomic ring) should count prime factors of prescribed splitting type, hence be constant on each hard family.

\textbf{D3. Equidistribution on the Weil circle.} For semiprimes with both factors $\equiv1\pmod4$, the normalised value $W(N)/(4\sqrt N)$ should have limiting distribution the multiplicative pushforward of two independent arcsine laws (Sato--Tate for CM curves), upgrading qualitative non-leakage to a quantitative $O(1)$-bit bound.

\textbf{D4. Density of near-attainment.} By Theorem~\ref{thm:near}, ``$W(p)^{2}>(1-\varepsilon)4p$ for a positive-density set of primes'' is equivalent to ``a positive-density set of primes $p\equiv1\pmod4$ has $p=a^{2}+b^{2}$ with $b=O(p^{\varepsilon/2})$''. The case $b=2$---primes $a^{2}+4$---is a well-known open problem of Landau type.

\textbf{D5. Arbitrary conics and character products.} Both halves of the argument generalise: multiplicativity holds for any weight that is a product of Jacobi-type characters at polynomials, and the per-prime bound follows from the same Jacobi-sum machinery. The expected statement is that any $S(N)=\sum_{(x,y)\in C(N)}w(x,y)$ with $C$ a conic and $w$ a product of character weights is multiplicative, of size $O(N^{1/2+o(1)})$, computable from $N$ in $N^{1+o(1)}$ and from the factorisation in $\mathrm{polylog}(N)$: the free-witness gap is exactly the Weil floor for the whole family at once.

\section{Conclusion}

The Jacobi-signed circle count is a genuinely interesting arithmetic function: multiplicative, computable without factoring, and equal at each prime $p\equiv1\pmod4$ to twice the odd leg of its two-square decomposition. It is also, provably, not a witness to factorisation. Every character weight yields at most two Jacobi sums and so obeys $|W_{\psi}(p)|\le2\sqrt p$ with an absolute constant; the deficiency in the Weil bound is exactly four times the square of the even Gaussian leg, giving the sharp $W(p)^{2}\le4p-16$; the $2$-adic valuation counts prime factors and is constant on the hard semiprime family; and multiplicativity itself is a free consequence of the Chinese Remainder Theorem, shared with conic weights that are outright constants. The square-root floor is not an artefact of a particular sum---it is the shape of the curve.

\end{document}

