"""A census of the Weil floor: attainment, deficiency, and semiprime blindness.

This script gathers statistical evidence for the four structure theorems, over all
primes and semiprimes in a chosen range:

  * the exact deficiency identity   4p - W(p)^2 = 4b^2   (checked, never violated);
  * the sharp floor  W(p)^2 <= 4p - 16, together with the list of primes attaining it
    (exactly the primes of the form a^2 + 4);
  * the distribution of the normalised value W(p) / (2 sqrt(p)) in [-1, 1], which for
    a curve with complex multiplication follows the arcsine law rather than Sato-Tate;
  * the constancy of the 2-adic valuation v2(W(pq)) = 2 across all semiprimes whose
    two prime factors are congruent to 1 modulo 4 -- the precise sense in which the
    statistic is blind to the split.

Only the Python standard library is used.
"""

from __future__ import annotations

import math
from typing import Dict, List, Tuple


def jacobi_symbol(a: int, n: int) -> int:
    a %= n
    result = 1
    while a != 0:
        while a % 2 == 0:
            a //= 2
            if n % 8 in (3, 5):
                result = -result
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            result = -result
        a %= n
    return result if n == 1 else 0


def signed_circle_count(n: int) -> int:
    return sum(jacobi_symbol((x - x ** 3) % n, n) for x in range(n))


def sieve(limit: int) -> List[int]:
    flags = [True] * (limit + 1)
    flags[0] = flags[1] = False
    for i in range(2, math.isqrt(limit) + 1):
        if flags[i]:
            for j in range(i * i, limit + 1, i):
                flags[j] = False
    return [i for i, f in enumerate(flags) if f]


def two_adic_valuation(m: int) -> int:
    v = 0
    while m % 2 == 0:
        m //= 2
        v += 1
    return v


def prime_census(limit: int) -> Tuple[List[Tuple[int, int, int, int]], List[int]]:
    """For every prime p = 1 (mod 4) below `limit`, return (p, W, a, b) and the
    list of primes attaining the sharp floor W^2 = 4p - 16."""
    rows: List[Tuple[int, int, int, int]] = []
    attaining: List[int] = []
    for p in sieve(limit):
        if p % 4 != 1:
            continue
        w = signed_circle_count(p)
        a = abs(w) // 2
        b = math.isqrt(p - a * a)
        assert a * a + b * b == p, (p, a, b)
        assert 4 * p - w * w == 4 * b * b
        assert w * w <= 4 * p - 16
        rows.append((p, w, a, b))
        if w * w == 4 * p - 16:
            attaining.append(p)
    return rows, attaining


def histogram(values: List[float], bins: int = 12) -> Dict[str, int]:
    counts = [0] * bins
    for v in values:
        idx = min(bins - 1, int((v + 1.0) / 2.0 * bins))
        counts[idx] += 1
    return {f"[{-1 + 2 * i / bins:+.2f},{-1 + 2 * (i + 1) / bins:+.2f})": c
            for i, c in enumerate(counts)}


def semiprime_census(prime_limit: int) -> Dict[int, int]:
    """Distribution of v2(W(pq)) over semiprimes with both factors 1 (mod 4)."""
    primes = [p for p in sieve(prime_limit) if p % 4 == 1]
    tally: Dict[int, int] = {}
    for i, p in enumerate(primes):
        for q in primes[i + 1:]:
            w = signed_circle_count(p) * signed_circle_count(q)   # multiplicativity
            v = two_adic_valuation(w)
            tally[v] = tally.get(v, 0) + 1
    return tally


def main() -> None:
    limit = 2000
    rows, attaining = prime_census(limit)
    print(f"Primes p = 1 (mod 4) below {limit}: {len(rows)}")
    print(f"  exact deficiency identity 4p - W^2 = 4b^2 verified for all of them")
    print(f"  sharp floor W^2 <= 4p - 16 verified for all of them")
    print(f"  attaining primes (p = a^2 + 4): {attaining}")

    ratios = [w / (2 * math.sqrt(p)) for (p, w, _, _) in rows]
    print("\nDistribution of W(p) / (2 sqrt p) -- the arcsine (CM) shape, peaked at the ends:")
    for interval, count in histogram(ratios).items():
        print(f"  {interval}  {'#' * count} ({count})")

    best = sorted(rows, key=lambda r: -(r[1] ** 2) / (4 * r[0]))[:8]
    print("\nClosest approaches to the floor:")
    print(f"  {'p':>6} {'W(p)':>7} {'b':>4} {'W^2/4p':>9}")
    for (p, w, _a, b) in best:
        print(f"  {p:>6} {w:>7} {b:>4} {w * w / (4 * p):>9.5f}")

    tally = semiprime_census(160)
    print("\n2-adic valuation of W(pq) over semiprimes with both factors 1 (mod 4):")
    for v, c in sorted(tally.items()):
        print(f"  v2 = {v}: {c} semiprimes")
    print("  -- a single value occurs, so the valuation cannot separate one split from another.")


if __name__ == "__main__":
    main()

