function W_FROM_MODULUS(N):                       # cost N^{1+o(1)}
    return sum over x = 0 .. N-1 of JACOBI(x - x^3 mod N, N)

function GAUSSIAN_LEGS(p):                        # p prime, p = 1 mod 4
    g <- least integer with JACOBI(g, p) = -1     # a quadratic non-residue
    r <- g^((p-1)/4) mod p                        # r^2 = -1 mod p
    (u, v) <- (p, r)
    while v > floor(sqrt(p)):                     # Euclidean descent
        (u, v) <- (v, u mod v)
    (a, b) <- (v, isqrt(p - v^2))
    if a is even: swap(a, b)                      # normalise: a odd, b even
    assert a^2 + b^2 = p
    return (a, b)

function W_FROM_FACTORS(p_1, ..., p_k):           # cost polylog(N)
    value <- 1
    for each prime p in p_1 .. p_k:
        if p mod 4 = 3: return 0                  # the whole product vanishes
        (a, b) <- GAUSSIAN_LEGS(p)
        value <- value * (sign) * 2a              # W(p) = +- 2a, a odd
    return value

function WEIL_REPORT(p):
    W <- W_FROM_FACTORS(p);  (a, b) <- GAUSSIAN_LEGS(p)
    return { W, odd leg a, even leg b,
             deficiency 4p - W^2, closed form 4b^2, sharp bound 4p - 16 }
